import os
import torch


class Config:
    """
    Configuration for the High-Capacity Stabilized Decoupled Bias-Refined BiGRU architecture.
    Centralizes all hyperparameters, data paths, and training settings.
    """

    # =========================================================================
    # Paths & Directories
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_62"
    SUBMISSION_DIR = "./submission"

    # Metadata Paths (Parquet files generated by metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Ensure working and submission directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LEN = 107
    SEQ_SCORED = 68

    # Input Features:
    # 4 (Bases: A, G, U, C)
    # + 3 (Structure: (, ), .)
    # + 7 (Loop Type: S, M, I, B, H, E, X)
    # = 14 channels
    INPUT_CHANNELS = 14

    # Targets (Multi-Task Learning on all 5 columns as per strategy)
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]

    # Columns used for validation scoring (MCRMSE)
    SCORED_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    NUM_TARGETS = len(TARGET_COLS)

    # =========================================================================
    # Model Hyperparameters
    # Architecture: High-Capacity Stabilized Decoupled Bias-Refined BiGRU
    # =========================================================================
    # Convolutional Stem
    CONV_FILTERS = 256
    CONV_KERNEL_SIZE = 3

    # Backbone (BiGRU)
    # Hidden dimension of 384 per direction (Total 768 internal state)
    HIDDEN_DIM = 384
    NUM_LAYERS = 4

    # Regularization
    DROPOUT = 0.1

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42

    # Compute
    # A100 40GB allows for larger batch sizes given the short sequence length (107)
    BATCH_SIZE = 64
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Optimization
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    EPOCHS = 25

    # Stability
    MAX_GRAD_NORM = 1.0  # Mandatory gradient clipping for hybrid architecture

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    MIN_LR = 1e-6

    # Early Stopping
    PATIENCE = 5

    # =========================================================================
    # Debugging & Development
    # =========================================================================
    # Set DEBUG to True to run on a small subset of data for quick pipeline verification
    DEBUG = False
    DEBUG_SUBSET_SIZE = 100
